from mk import *
from lib import fbd
STRICT["on"] = True

def fig():
    g = Fig(560, 150, "צעצוע וחתול יוצאים מהנקודה A ונעים לאורך קו ישר לכיוון הנקודה B")
    g.line(60, 90, 500, 90, width=1.8)
    g.add('<line x1="440" y1="90" x2="70" y2="90" stroke="var(--d-line)" stroke-width="1.8" marker-end="url(#f-axis)"/>')
    g.dot(450, 90); g.dot(200, 90)
    g.text(450, 74, "A"); g.text(200, 74, "B")
    g.circle(470, 70, 12, fill="var(--d-fill)", stroke="var(--d-line)"); g.heb(470, 50, "חתול")
    g.block(430, 108, 18, 12); g.heb(430, 138, "צעצוע")
    return g

def vgraph():
    g = Fig(560, 280, "גרף התשובה: מהירות החתול כפונקציה של הזמן. עולה בקו ישר מאפס עד 2 מטר לשנייה אחרי 2 שניות, קבועה עד 7 שניות, ויורדת לאפס אחרי 8 שניות")
    X, Y = g.graph(70, 240, 420, 180, "t (s)", "v (m/s)", xticks=[(t, str(t)) for t in range(1, 9)], yticks=[(1, "1"), (2, "2")], xmax=9, ymax=2.5)
    g.plot(X, Y, [(0, 0), (2, 2), (7, 2), (8, 0)])
    return g

E(id="bagrut-2016-q1", year=2016, label="2016 שאלה 1", topic="kinematics", sub="kin-straight-line", diff=3, fig=fig,
  stem=r"שמעון והחתול שלו משחקים: שמעון דוחף צעצוע על הרצפה, והצעצוע נע לאורך קו ישר מהנקודה $A$ לכיוון הנקודה $B$. באותו רגע החתול מתחיל לרוץ מאותה נקודה ובאותו כיוון. אפשר להזניח את התנגדות האוויר. החתול מאיץ ממנוחה בתאוצה קבועה של $1\,\text{m/s}^2$. אחרי $2$ שניות הוא ממשיך במהירות קבועה עוד $5$ שניות, ואז, בשנייה אחת נוספת, הוא מאט בקצב קבוע ונעצר בנקודה $B$.",
  parts=[
    P("א", r"שרטטו גרף של מהירות החתול כפונקציה של הזמן.", OPEN, ["graph"], [
        X(r"הכיוון החיובי הוא כיוון הריצה, מהנקודה A לנקודה B. בוחרים אותו, כי השאלה לא קבעה כיוון."),
        S(r"השלב הראשון", r"החתול יוצא ממנוחה בתאוצה קבועה, במשך שתי שניות", r"v(2) = 0 + 1 \cdot 2 = 2\,\text{m/s}", eq=r"v = v_0 + at"),
        S(r"השלב השני", r"מהירות קבועה במשך חמש שניות, עד הרגע שבע", r"v = 2\,\text{m/s}"),
        S(r"השלב השלישי", r"המהירות יורדת בקצב קבוע לאפס, בשנייה אחת", r"v(8) = 0"),
        D(r"הגרף: מהירות החתול כפונקציה של הזמן", vgraph),
    ], r"טרפז: עלייה עד $2\,\text{m/s}$ אחרי $2\,\text{s}$, מהירות קבועה עד $7\,\text{s}$, וירידה לאפס אחרי $8\,\text{s}$"),
    P("ב", r"מה המרחק בין הנקודה $B$ לנקודה $A$?", num(13, "m"), ["graph", "algebra"], [
        S(r"השטח מתחת לגרף", r"זה טרפז. הבסיס הגדול הוא כל זמן הריצה, הבסיס הקטן הוא השלב השני, והגובה הוא המהירות", r"AB = \frac{8 + 5}{2} \cdot 2 = 13\,\text{m}"),
        C(r"בדיקה לפי שלבים", r"משולש, מלבן ומשולש", r"\tfrac{1}{2} \cdot 2 \cdot 2 + 2 \cdot 5 + \tfrac{1}{2} \cdot 1 \cdot 2 = 2 + 10 + 1 = 13\,\text{m} \;\checkmark"),
    ], r"$13\,\text{m}$", key=r"13 m"),
    P("ג", r"שמעון נתן לצעצוע מהירות התחלתית בנקודה $A$. הצעצוע הגיע לנקודה $B$ שנייה וחצי לפני החתול, ונעצר בה. מקדם החיכוך $\mu$ בין הצעצוע לרצפה קבוע. מה המהירות ההתחלתית של הצעצוע?", num(4, "m/s"), ["principle", "algebra"], [
        S(r"זמן התנועה של הצעצוע", r"החתול הגיע אחרי שמונה שניות, והצעצוע שנייה וחצי לפניו", r"t = 8 - 1.5 = 6.5\,\text{s}"),
        S(r"משוואת המקום עם מהירות ממוצעת", r"החיכוך קבוע, ולכן התאוצה קבועה. הצעצוע מאט מהמהירות ההתחלתית עד אפס", r"13 = 0 + \frac{v_0 + 0}{2} \cdot 6.5", eq=r"x = x_0 + \frac{v_0 + v}{2}\,t"),
        S(r"מבודדים את המהירות ההתחלתית", r"מכפילים בשתיים ומחלקים בזמן", r"v_0 = \frac{2 \cdot 13}{6.5} = 4\,\text{m/s}"),
    ], r"$4\,\text{m/s}$", key=r"4 m/s"),
    P("ד", r"שרטטו תרשים של הכוחות שפועלים על הצעצוע, וחשבו את $\mu$.", num(0.4 / 6.5, ""), ["fbd", "principle", "algebra"], [
        D(r"תרשים הכוחות על הצעצוע", lambda: fbd([("mg", -90, 1.0), ("N", 90, 1.0), ("fₖ", 180, 0.55)],
            "תרשים כוחות על הצעצוע: כוח הכובד mg כלפי מטה, הכוח הנורמלי N כלפי מעלה, וכוח החיכוך הקינטי נגד כיוון התנועה. הכיוון החיובי הוא כיוון התנועה",
            positive=0, body="block", surface="below", note="הצעצוע מאט")),
        S(r"בוחרים כיוון חיובי", r"השאלה לא קבעה כיוון. בוחרים את כיוון התנועה, מהנקודה A לנקודה B", r"+ \;\rightarrow"),
        S(r"התאוצה", r"מהמהירות ההתחלתית לאפס, בזמן שמצאנו בסעיף ג. היא שלילית, כי הצעצוע מאט", r"a = \frac{0 - 4}{6.5} \approx -0.615\,\text{m/s}^2", eq=r"\bar a = \frac{\Delta v}{\Delta t}"),
        S(r"משוואת כוחות בציר האנכי", r"בציר הזה הצעצוע לא זז, ולכן הכוח הנורמלי שווה לכובד", r"N - mg = 0 \;\Rightarrow\; N = mg", eq=r"\Sigma\vec F = m\vec a"),
        S(r"משוואת כוחות בכיוון התנועה", r"בכיוון החיובי לא פועל אף כוח. נגדו פועל החיכוך", r"0 - f_k = m a", eq=r"f_k = \mu_k N"),
        S(r"מציבים את החיכוך", r"החיכוך הקינטי הוא מקדם החיכוך כפול הכוח הנורמלי", r"f_k = \mu_k N \;\Rightarrow\; -\mu_k N = m a"),
        S(r"מציבים את הכוח הנורמלי", r"מהמשוואה בציר האנכי", r"-\mu mg = m a"),
        S(r"מחלקים את משוואת הכוחות במסה", r"המסה מצטמצמת, ולכן לא צריך לדעת אותה", r"-\mu g = a \;\Rightarrow\; \mu = -\frac{a}{g} = \frac{0.615}{10} \approx 0.0615"),
    ], r"$\mu \approx 0.0615$", key=r"μ=0.0615"),
    P("ה", r"בפעם אחרת שמעון נתן לצעצוע אותה מהירות התחלתית, אבל הפעם מקדם החיכוך בין הצעצוע לרצפה גדול פי שניים ($\mu' = 2\mu$). איזה מהגדלים 1-4 לא משתנה? (1) התאוצה. (2) הזמן עד העצירה. (3) המרחק עד העצירה. (4) המהירות הממוצעת. נמקו.", choice(["1 התאוצה", "2 הזמן עד העצירה", "3 המרחק עד העצירה", "4 המהירות הממוצעת"], 3), ["principle", "understanding"], [
        S(r"התאוצה", r"לפי סעיף ד, גודל התאוצה פרופורציוני למקדם החיכוך, ולכן היא גדלה פי שניים", r"|a'| = \mu' g = 2\mu g = 2|a|"),
        S(r"הזמן עד העצירה", r"מתחלק בגודל התאוצה, ולכן קטן פי שניים", r"0 = v_0 - |a'|\,t' \;\Rightarrow\; t' = \frac{v_0}{2|a|} = \frac{t}{2}", eq=r"v = v_0 + at"),
        S(r"המרחק עד העצירה", r"גם הוא מתחלק בגודל התאוצה", r"0 = v_0^2 - 2|a'|\,d' \;\Rightarrow\; d' = \frac{v_0^2}{2 \cdot 2|a|} = \frac{d}{2}", eq=r"v^2 = v_0^2 + 2a(x - x_0)"),
        S(r"המהירות הממוצעת", r"בתאוצה קבועה היא ממוצע המהירות ההתחלתית והסופית, ושתיהן לא השתנו", r"\bar v = \frac{v_0 + 0}{2} = \frac{4}{2} = 2\,\text{m/s}"),
    ], r"(4) המהירות הממוצעת", key=r"4 - המהירות הממוצעת"),
  ],
  concepts=["גרף מהירות-זמן", "שטח כהעתק", "מהירות ממוצעת בתאוצה קבועה", "חיכוך קינטי", "תלות בפרמטר"],
  summary=r"חתול שרץ וצעצוע שמחליק ונעצר: מרחק מגרף, מהירות התחלתית ממהירות ממוצעת, מקדם חיכוך, ומה לא משתנה כשהחיכוך כפול.")
